CustomField.formula:
/*IF( ISPICKVAL(TSGCFG__Consolidation_Method__c, 'Average') && TSGCFG__TotalCPCLineItems__c > 0,
    TSGCFG__SumofCPCBW__c/  TSGCFG__TotalCPCLineItems__c,
    IF(ABS(TSGCFG__TotalBWVolume__c - TSGCFG__Total_Volume_Includes_B_W__c )<>0, TSGCFG__TotalBWMonthlyCost__c / ABS(TSGCFG__TotalBWVolume__c - TSGCFG__Total_Volume_Includes_B_W__c ),
        IF(TSGCFG__TotalCPCLineItems__c > 0,  TSGCFG__SumofCPCBW__c/  TSGCFG__TotalCPCLineItems__c , 0)
       )
   )
*/
IF( ISPICKVAL(TSGCFG__CPC_Consolidation__r.TSGCFG__Consolidation_Method__c, 'Average') && TSGCFG__CPC_Consolidation__r.TSGCFG__TotalCPCLineItems__c > 0,
    TSGCFG__CPC_Consolidation__r.TSGCFG__SumofCPCBW__c/  TSGCFG__CPC_Consolidation__r.TSGCFG__TotalCPCLineItems__c,
    IF(ABS(TSGCFG__CPC_Consolidation__r.TSGCFG__TotalBWVolume__c - TSGCFG__CPC_Consolidation__r.TSGCFG__Total_Volume_Includes_B_W__c )<>0, TSGCFG__CPC_Consolidation__r.TSGCFG__TotalBWMonthlyCost__c / ABS(TSGCFG__CPC_Consolidation__r.TSGCFG__TotalBWVolume__c - TSGCFG__CPC_Consolidation__r.TSGCFG__Total_Volume_Includes_B_W__c ),
        IF(TSGCFG__CPC_Consolidation__r.TSGCFG__TotalCPCLineItems__c > 0,  TSGCFG__CPC_Consolidation__r.TSGCFG__SumofCPCBW__c/  TSGCFG__CPC_Consolidation__r.TSGCFG__TotalCPCLineItems__c , 0)
       )
   )
